def cron_minutes(*args, **kwargs):
    if not args:
        return []
    s = args[0]
    parts = s.split(',')
    result = []
    for part in parts:
        if '-' in part:
            start, end = map(int, part.split('-'))
            result.extend(range(start, end + 1))
        else:
            result.append(int(part))
    return sorted(set(result))
